/* ATG i18n — in-page translator.
 * Replaces exact UI phrases using a per-app dictionary (generated by scripts/i18n/*).
 * Only phrases present in the dictionary are touched, so user data (names, amounts,
 * transaction descriptions) is never altered. Supports "{0}" patterns for text that
 * embeds a value, and keeps working as Alpine/JS add content after load.
 * Config: window.__ATG_I18N__ = { locale: 'fr', dict: { "Source": "Traduction" } }
 */
(function () {
  'use strict';
  var cfg = window.__ATG_I18N__;
  var root = document.documentElement;
  var reveal = function () { root.classList.remove('atg-i18n-pending'); };
  if (!cfg || !cfg.dict || !cfg.locale || cfg.locale === 'en' || cfg.locale === 'us') { reveal(); return; }

  var dict = cfg.dict;
  var norm = function (s) { return s.replace(/\s+/g, ' ').trim(); };
  // pattern entries ("Page {0} of {1}") → regexes
  var patterns = [];
  Object.keys(dict).forEach(function (k) {
    if (!/\{\d+\}/.test(k)) return;
    var parts = k.split(/(\{\d+\})/);
    var order = [];
    var re = parts.map(function (p) {
      var m = p.match(/^\{(\d+)\}$/);
      if (m) { order.push(+m[1]); return '(.+?)'; }
      return p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    }).join('');
    patterns.push({ re: new RegExp('^' + re + '$'), order: order, out: dict[k] });
  });

  var translate = function (text) {
    var t = norm(text);
    if (!t || t.length < 2) return null;
    if (Object.prototype.hasOwnProperty.call(dict, t)) return dict[t] !== t ? dict[t] : null;
    for (var i = 0; i < patterns.length; i++) {
      var m = t.match(patterns[i].re);
      if (m) {
        var out = patterns[i].out, ord = patterns[i].order;
        ord.forEach(function (n, idx) { out = out.split('{' + n + '}').join(m[idx + 1]); });
        return out;
      }
    }
    return null;
  };

  var SKIP = { SCRIPT: 1, STYLE: 1, CODE: 1, PRE: 1, TEXTAREA: 1, NOSCRIPT: 1, SVG: 1 };
  var ATTRS = ['placeholder', 'title', 'aria-label', 'alt'];
  var skipped = function (el) {
    for (var e = el; e && e !== document.body; e = e.parentElement) {
      if (SKIP[e.tagName] || e.isContentEditable || (e.hasAttribute && e.hasAttribute('data-no-translate'))) return true;
    }
    return false;
  };

  var doText = function (node) {
    var v = node.nodeValue;
    if (!v || !/[A-Za-z]/.test(v) || node.__atgOrig === v) return;
    var out = translate(v);
    if (out === null) return;
    var lead = v.match(/^\s*/)[0], trail = v.match(/\s*$/)[0];
    node.__atgOrig = lead + out + trail;            // remember what we wrote (avoid re-translating)
    node.nodeValue = node.__atgOrig;
  };
  var doEl = function (el) {
    for (var i = 0; i < ATTRS.length; i++) {
      var a = ATTRS[i], v = el.getAttribute(a);
      if (v && /[A-Za-z]/.test(v)) { var out = translate(v); if (out !== null) el.setAttribute(a, out); }
    }
    if ((el.tagName === 'INPUT') && /^(submit|button|reset)$/i.test(el.type) && el.value) {
      var o = translate(el.value); if (o !== null) el.value = o;
    }
  };
  var walk = function (rootNode) {
    if (!rootNode) return;
    if (rootNode.nodeType === 3) { if (!skipped(rootNode.parentElement)) doText(rootNode); return; }
    if (rootNode.nodeType !== 1 || skipped(rootNode)) return;
    doEl(rootNode);
    var tw = document.createTreeWalker(rootNode, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT, {
      acceptNode: function (n) { return n.nodeType === 1 && (SKIP[n.tagName] || n.hasAttribute('data-no-translate')) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT; },
    });
    for (var n = tw.nextNode(); n; n = tw.nextNode()) { if (n.nodeType === 3) doText(n); else doEl(n); }
    if (rootNode.tagName === 'HEAD' || rootNode === document.documentElement) { var tt = translate(document.title); if (tt) document.title = tt; }
  };

  var run = function () {
    walk(document.body);
    var tt = translate(document.title); if (tt) document.title = tt;
    reveal();
    // content added later (Alpine templates, fetch results, modals)
    new MutationObserver(function (muts) {
      muts.forEach(function (m) {
        if (m.type === 'characterData') { if (!skipped(m.target.parentElement)) doText(m.target); }
        else if (m.type === 'attributes') { if (!skipped(m.target)) doEl(m.target); }
        else m.addedNodes.forEach(function (n) { walk(n); });
      });
    }).observe(document.body, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ATTRS });
  };
  setTimeout(reveal, 900); // never leave the page hidden
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', run); else run();
})();
